sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var task = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task'); // querying custody task table to get the recent checker task
    var parRec = current.trade_case_id;
    task.addQuery('trade_case_id', parRec);
    task.addQuery('trade_task_type', 'Checker');
    task.orderByDesc('sys_created_on');
    task.query();
    if (task.next()) { // validating if decision is Reject and create a new task
        if (task.decision == 'Reject and create a new task') {
			if(task.decision_reason == 'Other'){
				current.work_notes = "Rejection Comments from the Checker: " + task.work_notes.getJournalEntry(1).match(/\n.*/gm).join('').replace(/^\s*\n/gm, "") + '\n' + "Rejected Checker Task Number : " + task.number; // adding the rejected checker task number along with the rejection comment
			}
			else{
				current.work_notes = "Rejection Comments from the Checker: " + task.decision_reason + '\n' + "Rejected Checker Task Number : " + task.number;
			}

        }
    }

})(current, previous);
